CREATE TABLE Advertisement (
    Advertisement_ID INTEGER PRIMARY KEY,
    Content VARCHAR(255),
    Name VARCHAR(255)
);

CREATE TABLE User (
    Contact_Information VARCHAR(255),
    Name VARCHAR(255),
    User_ID INTEGER PRIMARY KEY
);

CREATE TABLE Broadcast_Record (
    Advertisement_ID INTEGER NOT NULL,
    Time_Slot DATETIME,
    PRIMARY KEY (Advertisement_ID, Time_Slot),
    FOREIGN KEY (Advertisement_ID) REFERENCES Advertisement(Advertisement_ID)
);

CREATE TABLE Advertisement_Push (
    Advertisement_ID INTEGER NOT NULL,
    User_ID INTEGER NOT NULL,
    PRIMARY KEY (Advertisement_ID, User_ID),
    FOREIGN KEY (Advertisement_ID) REFERENCES Advertisement(Advertisement_ID),
    FOREIGN KEY (User_ID) REFERENCES User(User_ID)
);
